<?php
declare(strict_types=1);
use Vendi\Database\Connection;use Vendi\Http\ApiGuard;use Vendi\Branches\BranchContextService;use Vendi\Reports\SalesReportService;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');
try{$u=ApiGuard::session();ApiGuard::permission('reports.view');$db=Connection::get();$b=(int)$u['business_id'];$ctx=new BranchContextService($db);$branch=(int)$ctx->activeBranchId($u);ApiGuard::branch($branch);$from=(string)($_GET['from']??date('Y-m-d'));$to=(string)($_GET['to']??$from);if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))throw new RuntimeException('Rango de fechas inválido.');$type=(string)($_GET['type']??'movements');$s=new SalesReportService($db);$data=match($type){'movements'=>$s->movements($b,$branch,$from,$to),'weekday'=>$s->byWeekday($b,$branch,$from,$to),'hour'=>$s->byHour($b,$branch,$from,$to),'cancelled'=>$s->cancelled($b,$branch,$from,$to),'held'=>$s->held($b,$branch),default=>throw new RuntimeException('Reporte no reconocido.')};echo json_encode(['ok'=>true,'type'=>$type,'data'=>$data],JSON_UNESCAPED_UNICODE);}catch(Throwable$e){http_response_code(400);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
